    const q = `%${query}%`;
    const { data, error } = await client.from("assets").select("id, asset_name, category, serial_number, status, quantity").or(`asset_name.ilike.${q},category.ilike.${q},serial_number.ilike.${q}`).limit(limit ?? 25);
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
