import { createClient as createClient6 } from "npm:@supabase/supabase-js@^2.99.1";
import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z4 } from "npm:zod@^3.25.76";
function sb6(ctx) {
  return createClient6(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
var post_relay_message_default = defineTool6({
  name: "post_relay_message",
  title: "Post a Relay message on a job",
  description: "Post a message into the Relay chat for a job as the signed-in user. Use for status updates, questions, or notes. RLS enforces that the caller can post on this job.",
  inputSchema: {
    job_id: z4.string().uuid().describe("Job UUID to post into."),
    message: z4.string().trim().min(1).max(2e3).describe("Message text.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
  handler: async ({ job_id, message }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const client = sb6(ctx);
    const { data: emp } = await client.from("employees").select("id, name, role").eq("user_id", ctx.getUserId()).maybeSingle();
    const senderRole = (emp?.role ?? "").toLowerCase();
    const sender_type = senderRole === "admin" || senderRole === "manager" ? "manager" : senderRole === "operator" ? "operator" : "user";
    const { data, error } = await client.from("relay_messages").insert({
      job_id,
      sender_id: ctx.getUserId(),
      sender_name: emp?.name ?? ctx.getUserEmail() ?? "MCP client",
      sender_type,
      message
    }).select().single();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: `Posted message ${data.id}` }],
      structuredContent: { message: data }
    };
  }
});

